const crypto = require('crypto');
const {getDatabase}=require('../_db');
function parseCookies(request){return Object.fromEntries(String(request.headers.cookie||'').split(';').filter(Boolean).map(item=>{const i=item.indexOf('=');return [item.slice(0,i).trim(),decodeURIComponent(item.slice(i+1).trim())]}))}
function hashPassword(password){const salt=crypto.randomBytes(16).toString('hex');return `scrypt$${salt}$${crypto.scryptSync(String(password),salt,64).toString('hex')}`}
function verifyPassword(password,stored){const [,salt,expected]=String(stored||'').split('$');if(!salt||!expected)return false;const actual=crypto.scryptSync(String(password||''),salt,64).toString('hex');return crypto.timingSafeEqual(Buffer.from(actual,'hex'),Buffer.from(expected,'hex'))}
function sessionToken(user){const secret=process.env.ADMIN_SESSION_SECRET;if(!secret)throw new Error('ADMIN_SESSION_SECRET não configurada');const payload=Buffer.from(JSON.stringify({id:user.id,login:user.login||user.email,nomeExibicao:user.nome_exibicao||user.nome,perfil:user.perfil,exp:Date.now()+8*60*60*1000})).toString('base64url');return payload+'.'+crypto.createHmac('sha256',secret).update(payload).digest('base64url')}
function currentUser(request){const token=parseCookies(request).jll_admin_session;const secret=process.env.ADMIN_SESSION_SECRET;if(!token||!secret)return null;const [payload,signature]=token.split('.');if(!payload||!signature)return null;const expected=crypto.createHmac('sha256',secret).update(payload).digest('base64url');if(signature.length!==expected.length||!crypto.timingSafeEqual(Buffer.from(signature),Buffer.from(expected)))return null;try{const data=JSON.parse(Buffer.from(payload,'base64url').toString());return data.exp>Date.now()?data:null}catch{return null}}
async function authenticatedUser(request){const session=currentUser(request);if(!session)return null;const sql=getDatabase();const rows=await sql`SELECT id,nome_exibicao,nome_completo,login,perfil FROM usuarios_atendimento WHERE id=${session.id} AND ativo=TRUE LIMIT 1`;return rows[0]||null}
module.exports={hashPassword,verifyPassword,sessionToken,currentUser,authenticatedUser};
